    rail_score = -1
    for v in colors:
        score = sum(cell == v for row in g for cell in row)
        if score > rail_score:
            rail, rail_score = v, score
    mark_colors = [v for v in colors if v != rail]
    mark_color = mark_colors[0] if mark_colors else None
    marks = [(r, c) for r in range(h) for c in range(w)
             if g[r][c] == mark_color] if mark_color is not None else []

    # Two opposing vertical edge bars divide the grid into matched row bands.
    left_rows = [r for r in range(h) if g[r][0] == rail]
    right_rows = [r for r in range(h) if g[r][w - 1] == rail]
    if left_rows and right_rows and marks:
        def runs(indices):
            out = []
            for x in indices:
                if not out or x != out[-1][-1] + 1:
                    out.append([x])
