 "content": "from collections import Counter


def _runs(indices):
    out = []
    for x in indices:
        if not out or x != out[-1][-1] + 1:
            out.append([x])
        else:
            out[-1].append(x)
    return out


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != bg]
    if len(colors) < 2:
        return g
    rail = max(colors, key=lambda v: counts[v])
    seeds = [v for v in colors if v != rail]
    if not seeds:
        return g
    mark = seeds[0]
    points = [(r, c) for r in range(h) for c in range(w) if g[r][c] == mark]
    if not points:
        return g

    # Vertical edge rails: draw a horizontal line from each seed to its rail,
    # then mirror the row's color across the gap to the opposite rail segment.
    left = _runs([r for r in range(h) if g[r][0] == rail])
    right = _runs([r for r in range(h) if g[r][w - 1] == rail])
    if len(left) == len(right) == 1 and len(left[0]) == len(right[0]):
        l0, l1 = left[0][0], left[0][-1]
        r0, r1 = right[0][0], right[0][-1]
        for r, c in points:
            if l0 <= r <= l1:
                edge, base, paired_base = 0, l0, r0
            elif r0 <= r <= r1:
                edge, base, paired_base = w - 1, r0, l0
            else:
                continue
            lo, hi = sorted((edge, c))
            for cc in range(lo + 1, hi):
                if g[r][cc] == bg:
                    g[r][cc] = mark
            g[r][c] = 4
            paired = paired_base + (r - base)
            if 0 <= paired < h:
                for cc in range(w):
                    if g[paired][cc] == bg:
                        g[paired][cc] = mark
        return g

    # Horizontal edge rails: extend top-rail columns down, and each seed
    # downward to the lower rail; mark seed endpoints with color 4.
    top = _runs([c for c in range(w) if g[0][c] == rail])
    bottom = _runs([c for c in range(w) if g[h - 1][c] == rail])
    if top and bottom:
        for run in top:
            for c in run:
                for r in range(1, h - 1):
                    if g[r][c] == bg:
                        g[r][c] = mark
        for r, c in points:
            if 0 < r < h - 1:
                for rr in range(r + 1, h - 1):
                    if g[rr][c] == bg:
                        g[rr][c] = mark
                g[r][c] = 4
        return g
    return g
